labels = {tag: value + "|" + losses[tag] for tag, value in labels.items()}
path = Path(__file__).with_name("catalog.json")
catalog = json.loads(path.read_text(encoding="utf-8"))
assert set(labels) == set(catalog["locales"])
for tag, text in labels.items():
    values = text.split("|")
    assert len(values) == len(keys)
    for key, value in zip(keys, values):
        if key not in catalog["keys"]:
            catalog["keys"].append(key)
        index = catalog["keys"].index(key)
        rows = catalog["locales"][tag]
        if index == len(rows):
            rows.append(value)
        else:
            rows[index] = value
path.write_text(json.dumps(catalog, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
